<?php
namespace Azuriom\Plugin\GamingHubCore\Services;
use Azuriom\Plugin\GamingHubCore\Contracts\CapabilityReader; use Azuriom\Plugin\GamingHubCore\Contracts\CapabilityReaderRegistry; use Azuriom\Plugin\GamingHubCore\Contracts\ProviderTypeRegistry; use Azuriom\Plugin\GamingHubCore\Exceptions\DuplicateCapabilityReader; use Azuriom\Plugin\GamingHubCore\Exceptions\InvalidCapabilityReader;
final class InMemoryCapabilityReaderRegistry implements CapabilityReaderRegistry { private array $readers=[]; public function __construct(private ProviderTypeRegistry $types){} public function register(string $providerType,string $capability,string $readerClass):void{$type=$this->types->get($providerType);if(!$type->supports($capability))throw new InvalidCapabilityReader("Provider type [$providerType] does not support [$capability].");if(!is_a($readerClass,CapabilityReader::class,true))throw new InvalidCapabilityReader('Reader must implement CapabilityReader.');$key=$providerType.'|'.$capability;if(isset($this->readers[$key]))throw new DuplicateCapabilityReader("Reader already registered for [$key].");$this->readers[$key]=$readerClass;} public function has(string $p,string $c):bool{return isset($this->readers[$p.'|'.$c]);} public function readerClass(string $p,string $c):?string{return $this->readers[$p.'|'.$c]??null;} }
